<script>document.addEventListener('DOMContentLoaded',()=>{const n=document.querySelector('[data-site-navbar]'),t=n?.querySelector('[data-site-nav-toggle]'),l=n?.querySelector('[data-site-nav-links]'),h=document.querySelector('.hero');if(!n||!t||!l)return;const s=o=>{n.classList.toggle('is-open',o);t.setAttribute('aria-expanded',String(o));t.querySelector('i').className=o?'ri-close-line':'ri-menu-3-line'},mix=(a,b,p)=>Math.round(a+(b-a)*p),u=()=>{const distance=Math.max(1,(h?.offsetHeight||320)-n.offsetHeight),p=Math.min(1,Math.max(0,window.scrollY/distance)),smooth=p*p*(3-2*p);n.style.setProperty('--nav-bg-alpha',(smooth*.96).toFixed(3));n.style.setProperty('--nav-border-alpha',(smooth*.25).toFixed(3));n.style.setProperty('--nav-shadow-alpha',(smooth*.08).toFixed(3));n.style.setProperty('--nav-text-shadow',(.6*(1-smooth)).toFixed(3));n.style.setProperty('--nav-text-color',`rgb(${mix(255,7,smooth)} ${mix(255,86,smooth)} ${mix(255,106,smooth)})`);n.style.setProperty('--nav-accent-color','#f66243');n.style.setProperty('--nav-cta-bg',`rgb(${mix(246,2,smooth)} ${mix(98,173,smooth)} ${mix(67,208,smooth)})`);n.style.setProperty('--nav-cta-text','#fff');n.style.setProperty('--nav-toggle-border',(.34*(1-smooth)).toFixed(3));n.style.setProperty('--nav-toggle-bg',smooth>.55?'#07566a':'rgba(255,255,255,.09)');n.classList.toggle('is-scrolled',p>=.98)};t.addEventListener('click',()=>s(!n.classList.contains('is-open')));l.addEventListener('click',()=>s(false));document.addEventListener('click',e=>{if(!n.contains(e.target))s(false)});window.addEventListener('scroll',u,{passive:true});window.addEventListener('resize',u,{passive:true});u()});</script>
